"""Add accessible-content and privacy-integration curriculum to local drafts."""
import copy
import datetime
import html
import json
import re
import subprocess
import uuid
from pathlib import Path

root = Path(__file__).resolve().parents[1]
fixture = root / 'src/data/fixtures.json'
entries = json.loads(fixture.read_text())
by_path = {entry['path']: entry for entry in entries}
stamp = datetime.datetime.now(datetime.UTC).isoformat()

def p(value):
    return '<p>' + html.escape(value) + '</p>'

def link(path):
    title = by_path[path]['title'] if path in by_path else next((item['title'] for item in lessons if item['path'] == path), None)
    assert title is not None, path
    return '<a href="/' + html.escape(path, quote=True) + '">' + html.escape(title) + '</a>'

hubs = [
    dict(path='web-tech/accessible-content-and-media', title='Accessible Content and Media', summary='Carry image, chart, audio, video, and page structure meaning into equivalent readable paths.', overview='Interface accessibility also depends on the content authors place inside it. An image can be informative in one context and decorative in another. A chart can hide the values needed for a decision. A recording can contain speech, sounds, and visual actions that a single text track cannot convey. This track uses an inspection-report workflow and asks what information the user needs, then makes that information available through text, structure, and usable controls.', bridges=['web-tech/inclusive-interface-engineering','web-tech/image-variants-and-delivery']),
    dict(path='web-tech/privacy-aware-external-integrations', title='Privacy-Aware External Integrations', summary='Inventory third-party requests, gate optional services, minimize events, and honor preference changes.', overview='A page can send private information before a user submits a form. Remote scripts, embeds, pixels, and analytics calls can receive URLs, referrers, identifiers, and event properties. Browser storage behavior changes across contexts, so an embedded tool cannot assume unrestricted cookies. This track uses a case-review product with optional analytics and a support widget. The engineering task is to identify each external data path, keep the core review flow usable without it, and apply the product’s approved preference and retention policy consistently.', bridges=['web-tech/browser-security-and-data-stewardship','web-tech/data-retention-export-and-erasure']),
]

lessons = [
    dict(hub=0, path='web-tech/image-alternatives-by-purpose', title='Image Alternatives by Purpose', summary='Write image alternatives for the task the image performs, including decorative and functional cases.',
    definition='Alternative text gives a nonvisual reader the information or function carried by an image in its current context. It is not a mandatory inventory of every visible pixel. A decorative separator contributes no information and should have an empty alternative. A linked icon needs a name that communicates the destination or action; a screenshot used as evidence needs the fact a reviewer must assess. The same photo may require different words on a case card and inside a detailed report. Treat its purpose as editorial data attached to a placement, not merely as a property of the file.',
    case='An inspection report contains a photo of a damaged blue pipe labeled P-47. On the case list, the image is a thumbnail beside visible text saying Damaged pipe P-47, so repeating the same sentence in the image alternative may add noise. In the evidence detail, the image shows a crack near the upper valve that is not stated elsewhere; that fact belongs in the alternative or adjacent description. A magnifying-glass icon opens a zoom view and needs the action name View larger evidence photo. A colored stripe separating reports is decorative.',
    implementation='Model each placement with a purpose such as decorative, informative, or functional and store an editor-approved alternative where needed. Do not generate the same file-level text for every context. Give decorative images an explicit empty alternative so assistive technology does not read a filename. Avoid phrases that merely announce the image element when its role is already conveyed. If a functional image is the only content of a link or button, the control needs a usable name even when the image fails. Put essential visible text from an image in real text when possible, and keep translations aligned with the report locale.',
    cost='Rendering a short alternative is O(1) work, but authoring and review scale with the number of meaningful placements rather than the number of unique files. Duplicating a file-level label across many contexts saves editorial time while losing intent. Overlong descriptions slow sequential reading and still may omit the decision-relevant fact. Record coverage by purpose category, not simply the fraction of images with nonempty strings. Visual QA should turn images off and inspect whether the report remains understandable; assistive-technology review is still needed for order and control names.',
    failure='A build check insists every image have nonempty alt text, so decorators acquire labels such as blue line and functional icons get the vague word icon. The page becomes noisy while the zoom button remains unclear. Replace the rule with a placement decision and verify both empty decorative alternatives and meaningful control names. Another failure describes only the color of the pipe while the crack is the reason for escalation. Ask a reviewer to complete the case decision without seeing the photo. If the necessary fact is missing, revise the alternative or the adjacent prose.',
    drill='Review twenty report images: identify each placement’s purpose, the decision it supports, and whether nearby text already carries the fact. Test a linked icon with images disabled, a repeated thumbnail beside a visible title, and a detailed evidence photo with a hidden defect. Change the report locale and check translated alternatives. Add a content check that catches missing decisions without forcing meaningless nonempty text on decorative media.',
    decision='Describe the image’s function or missing information in context; use an explicit empty alternative when it adds no information.',
    code='function alternativeForPlacement(placement) {\n  if (placement.purpose === "decorative") return "";\n  if (placement.purpose === "action") return placement.actionName;\n  return placement.decisionFact;\n}\nconsole.log(alternativeForPlacement({ purpose: "action", actionName: "View larger evidence photo" }));\n// Output: View larger evidence photo',
    checks=['A meaningful photo conveys its decision-relevant fact without sight.','A decorative image is skipped without announcing a filename.','An image-only control has a clear action name.'], mistakes=['Using one file-level alternative for every placement.','Forcing nonempty text on decorative artwork.','Naming an icon by appearance while hiding its action.'], related=['web-tech/accessible-names-and-native-controls','web-tech/image-variants-and-delivery','web-tech/structured-data-visible-facts']),
    dict(hub=0, path='web-tech/chart-and-diagram-text-equivalents', title='Chart and Diagram Text Equivalents', summary='Expose chart values and conclusions as structured text without making color or position the only signal.',
    definition='A chart compresses numbers and relationships into a visual form. A short alternative can identify what the chart is about, but it cannot carry every data point or relationship a reader may need. Provide the important result in nearby prose and give access to the underlying values or a structured explanation. The equivalent should answer the same task as the graphic: identifying a trend, comparing cases, or finding an outlier. Color, symbol position, and hover tooltips alone cannot serve as the only channel for that information. The data revision shown in text must match the rendered chart.',
    case='A case dashboard plots unresolved inspections by district across four weeks. District North rises from 23 to 47, while East falls from 42 to 31. The visual bars make the difference quick to see, but a reviewer also needs exact values and the date range. Place a concise statement of the meaningful change before the chart, then offer a text list of weekly district counts in a sensible order. A diagram of the review process needs its branch conditions and outcomes in text, not just colored arrows that disappear when the image fails.',
    implementation='Build the chart and its text equivalent from the same normalized data object and revision so they cannot silently diverge. A short image alternative identifies the visual, while visible text or a linked detail supplies the values and relationship. For interactive charts, do not rely on hover alone; keyboard users need a way to reach data points, or a text representation that supports the same question. Label units, time zone, and missing-data rules. If a chart aggregates private records, authorize the text equivalent and downloadable values under the same policy as the graphic.',
    cost='Producing a textual list of n data points is O(n) time and output space. For thousands of points, a full inline listing can overwhelm readers, so provide meaningful summary, filters, and an accessible data view with pagination or an approved export. A second manually maintained summary is cheaper to implement today but becomes inaccurate after data updates. Reusing a normalized data model costs design work and reduces drift. Test that the largest, smallest, and missing values in the text match the chart’s current revision and permissions.',
    failure='The dashboard adds a short alternative reading bar chart but no values or trend in text. A reviewer cannot determine which district crossed an escalation threshold without seeing the bars. Add a plain-language result and data access path. Another chart uses red and green alone to encode status; monochrome viewing loses the meaning. Provide explicit labels and values. Change a filter from All districts to North and confirm the summary and text values update together. A stale text equivalent can be worse than no summary because it looks authoritative.',
    drill='Start with the four-week district dataset and write three questions the chart is supposed to answer. Verify each can be answered from text alone. Remove colors, disable hover, use keyboard only, and inspect the filtered state with a screen reader. Change one underlying count and assert that the chart, result sentence, and value list use the same revision. Try an unauthorized district account and verify neither graphic nor text reveals protected counts.',
    decision='Give complex visuals a concise identity and a synchronized text path to the actual data and conclusion.',
    code='function districtChange(firstWeek, lastWeek) {\n  return { direction: lastWeek >= firstWeek ? "up" : "down", amount: Math.abs(lastWeek - firstWeek) };\n}\nconsole.log(JSON.stringify(districtChange(23, 47)));\n// Output: {"direction":"up","amount":24}',
    checks=['A reader can answer the chart’s core questions from text.','Text and visual states share the same filter and revision.','Protected aggregates remain protected in both presentations.'], mistakes=['Using a generic chart label as the entire equivalent.','Encoding status only by color or hover.', 'Maintaining chart and text values in separate unsynchronized data paths.'], related=['web-tech/data-table-versus-interactive-grid','web-tech/structured-data-visible-facts','web-tech/search-permissions-and-private-results']),
    dict(hub=0, path='web-tech/captions-transcripts-and-media-controls', title='Captions, Transcripts, and Media Controls', summary='Match speech, meaningful sound, and visual action to accessible tracks and usable playback controls.',
    definition='Timed media can carry meaning in several channels at once. Captions provide synchronized text for speech and meaningful sounds in audio. A transcript supports reading or searching the content without following the timeline, and a descriptive transcript can also include visual facts that speech omits. Audio description or an integrated spoken description is needed when visual events are essential and not already in the main audio. A player must expose controls that work with keyboard and assistive technology. None of these substitutes for verifying the actual content against the recording.',
    case='A training clip shows an inspector closing valve V-62. The narrator says Close the valve while the video silently shows that the lever must turn clockwise and stop at a red mark. Captions of the narrator alone omit the essential visual instruction. Add a spoken or textual description of the turning direction and stop position, then keep captions synchronized with speech and the alarm sound that follows. A transcript lets an operator search for the valve identifier without replaying the whole clip. The player must permit pause and replay before the next step.',
    implementation='Treat captions and transcripts as versioned companions of a specific media revision. Store language and timing metadata, and invalidate or re-review tracks whenever the clip is recut. Use a player with native or equivalent keyboard-operable controls, visible focus, caption selection, and a documented fallback if a track fails to load. Avoid autoplay that starts unexpected audio. Do not assume machine-generated captions are accurate enough for technical instructions; review names, numbers, sound cues, and timing. Media access controls must apply to tracks and transcripts as well as to the video file.',
    cost='A transcript adds storage proportional to the recording’s words, while captions also store time cues. Playback itself is dominated by media transfer and decoding, not by rendering a short text track. Editorial review takes time, especially after a clip changes, but a wrong valve number has a real operational cost. Loading every language track up front may waste bandwidth; select and fetch the needed one while preserving a usable default. Measure track load failures, keyboard completion, caption timing drift, and transcript-to-video revision mismatches.',
    failure='A generated caption says valve V-26 where the narrator says V-62. The transcript is indexed for search, so operators also find the wrong procedure. Add technical review and a revision check before release. Another clip has perfect captions but gives no description of the clockwise motion, leaving a nonvisual user without the key instruction. Test the task with audio only, captions only, and transcript only. Hide the video file from an unauthorized account and confirm its caption and transcript routes are equally restricted.',
    drill='Prepare a ninety-second clip with speech, an alarm, and a silent but necessary hand movement. Write timed captions and a descriptive transcript. Ask a tester to identify the valve, direction, and stopping point using only the text alternatives. Check keyboard play, pause, seek, captions, and focus. Recrop the clip to change timing and verify that stale tracks are rejected or reviewed again before publication.',
    decision='Version and review each alternative against the media, then test the actual task through every required channel.',
    code='function mediaReleaseReady(mediaRevision, tracks) {\n  return tracks.every(track => track.reviewedRevision === mediaRevision);\n}\nconsole.log(mediaReleaseReady(7, [{ reviewedRevision: 7 }, { reviewedRevision: 6 }]));\n// Output: false',
    checks=['Speech and meaningful sounds are represented in timed captions.','Essential visual actions appear in a descriptive channel.','Track access, revision, and player controls match the media.'], mistakes=['Publishing unreviewed technical captions.','Assuming speech captions describe silent visual instructions.','Protecting a video while leaving its transcript public.'], related=['web-tech/image-variants-and-delivery','web-tech/accessible-names-and-native-controls','web-tech/inclusive-interface-engineering']),
    dict(hub=0, path='web-tech/landmarks-headings-and-skip-paths', title='Landmarks, Headings, and Skip Paths', summary='Preserve page orientation and bypass routes as client navigation changes content.',
    definition='Page structure gives readers a map. Landmarks identify major regions, headings describe their hierarchy, and a skip path lets keyboard users bypass repeated navigation. These are not decorative style hooks. A page with several unlabeled navigation regions or headings chosen only for font size may be hard to understand out of order. Client-side routing adds another boundary: the document may change while focus stays on the old link, and a new visual heading does not automatically announce that the page changed. Structure and route focus need to be designed together.',
    case='A case-review app has global navigation, a case-specific menu, and the report body. Both navigation regions need distinct labels. A keyboard user arriving at the page can activate Skip to report and land at the main region without crossing the same controls every time. Opening case 47 from a search result changes the route and displays an Inspection report heading. The app sets the document title and moves focus or announces the new main heading according to its route contract, while preserving expected browser back behavior.',
    implementation='Use semantic page regions for header, navigation, main content, and footer. Give repeated landmarks distinct accessible names and keep one clear primary main region for the route. Make the skip control visible when focused and ensure its target can receive focus when needed. Write headings for information structure, then style them separately from rank. During a client route change, avoid leaving focus on a removed element; move it to a meaningful route heading or status target after content is ready. An in-page filter change should use a different announcement pattern from a full route transition.',
    cost='Semantic structure adds negligible runtime work, but route focus effects can trigger extra rendering or scrolling if fired repeatedly. Limit the focus move to completed navigations, not each data refresh. Too many landmarks create another long list to scan, so group regions by real purpose. A skip link requires ongoing maintenance when layouts change; its target must still exist in loading and error states. Test with a keyboard and a screen-reader landmark or heading list, not only with a DOM inspector. Measure whether a user can reach the report efficiently from every route state.',
    failure='A design system renders every visually large label as an h2, including sidebar counts and button labels. Heading navigation becomes a list of noise while the actual report sections are missing. Separate visual typography from semantic headings. Another SPA changes the case title but leaves focus on the search result that has just unmounted; the reader has no clear arrival cue. Test direct load, internal navigation, back, error, and delayed data. Ensure Skip to report is still usable before and after the route transition.',
    drill='Map landmarks and heading levels for a search page, case detail, and note editor. Verify the two navigation regions have distinct names, the skip control lands in main content, and heading order conveys the report outline. Start at a search result with keyboard only, open case 47, go back, and open case 62 while observing focus and title. Simulate a delayed report and a route error, then check that focus is not sent to a missing heading.',
    decision='Keep the page map meaningful in every route state and move focus intentionally when the route changes.',
    code='function routeArrivalTarget(routeState) {\n  if (routeState === "ready") return "report-heading";\n  if (routeState === "error") return "route-error-heading";\n  return "loading-status";\n}\nconsole.log(routeArrivalTarget("error"));\n// Output: route-error-heading',
    checks=['Repeated landmarks have distinct names and the main region is clear.','The skip path reaches meaningful content from the top of the page.','Route changes leave focus on a present, informative target.'], mistakes=['Choosing heading levels for visual size alone.','Leaving focus on a removed route link.','Hiding a skip control even when it receives keyboard focus.'], related=['web-tech/route-scroll-and-focus-restoration','web-tech/accessible-names-and-native-controls','web-tech/inclusive-interface-engineering']),
    dict(hub=1, path='web-tech/third-party-request-and-script-inventory', title='Third-Party Request and Script Inventory', summary='Record what external code and embeds receive before deciding whether they belong on a page.',
    definition='An external script executes in the page’s origin and can often inspect the DOM, make requests, and read data available to ordinary page script. An embedded frame has a separate origin boundary, but it still receives a request with some context and may ask for additional capabilities. Before installing either, identify its purpose, owner, loading condition, data fields, network destinations, and failure behavior. A dependency list alone is insufficient: a script can load more scripts or transmit data through pixels and beacons. Inventory the observed request graph, including after user actions and route changes.',
    case='A case-review dashboard adds a support widget that loads before sign-in completes. Its remote script sees the full route containing case 47 and sends page-view events even when the widget is never opened. A separate analytics tag sends the reviewer’s name as a property. Move the optional widget behind a deliberate user action and use a scoped embed or server-mediated integration where appropriate. Remove private identifiers from page URLs and event payloads. The report-reading task must continue if both external services fail or are unavailable.',
    implementation='Maintain a registry for each third-party integration with its owner, purpose, allowed origins, data contract, loading trigger, version, and removal plan. Inspect network traffic on initial load, authenticated routes, and after interactions; include redirects and resources loaded by the vendor. Restrict scripts using the platform’s security controls where applicable, while recognizing that a same-origin script can still access page data. Use frame sandbox and capability policy deliberately for embeds, then test the features they truly require. Avoid treating an allowlist as a privacy policy: it controls destinations, not the meaning of data sent.',
    cost='A remote script increases bytes, connection work, parsing, and main-thread execution even before it provides value. Network inventory has a review cost each release because vendors can change resources without changing your code. A lazy or on-demand embed can reduce initial load and data exposure but adds a click before the support action. Measure initial bytes, long tasks, failure impact, external request count, and unexpected destination changes. A smaller script bundle does not prove privacy if one beacon still carries a case identifier.',
    failure='A team removes a script tag from the template but leaves a marketing pixel injected by a tag manager. The request inventory still shows the external destination. Audit runtime network traffic rather than relying on source search alone. Another integration claims a sandboxed frame is harmless, yet the parent sends private case notes to it through messages. Inspect message payloads and origin checks. Test with the vendor blocked and verify no case-review route crashes. Capture the request graph before and after enabling the widget, then review every new field.',
    drill='Open a signed-out page and two private case routes with a clean browser profile. Record every external request, method, destination, initiator, query string, referrer behavior, and event property. Activate the support widget and compare graphs. Block the remote origin and repeat the core task. Review a frame message exchange and a vendor update that adds a new destination. Require a named owner to approve or remove the new path before release.',
    decision='Approve external integrations from observed requests and data contracts, not from package names or visual appearance.',
    code='function unexpectedDestinations(observedHosts, approvedHosts) {\n  return observedHosts.filter(host => !approvedHosts.has(host));\n}\nconsole.log(unexpectedDestinations(["metrics.internal", "widget.partner"], new Set(["metrics.internal"])).join(","));\n// Output: widget.partner',
    checks=['Every external request has a purpose, owner, and data contract.','Private case routes do not leak identifiers through events or referrers.','The core task survives vendor failure or blocking.'], mistakes=['Assuming a package inventory captures runtime requests.','Treating an embedded frame as proof no data is shared.','Loading an optional vendor before the user needs it.'], related=['web-tech/embedding-and-browser-capability-headers','web-tech/dependency-integrity-and-update-window','web-tech/telemetry-minimization-and-retention']),
    dict(hub=1, path='web-tech/optional-analytics-event-boundaries', title='Optional Analytics Event Boundaries', summary='Separate operational signals from optional measurement and constrain event fields before collection.',
    definition='An analytics event is a data transfer with a schema and purpose. It can expose more than its event name: route paths, query strings, device identifiers, account IDs, and free-text properties may contain private case information. Distinguish signals needed to operate and secure the service from optional product measurement, then apply the organization’s approved choice and retention rules to each category. The choice has to affect collection before an event is sent, not merely hide a dashboard later. Aggregation does not undo a leak that already reached an external recipient.',
    case='The review team wants to know how often the Export action is used. The old event includes case ID, reviewer email, current URL, and the full export filter. None is needed to count action starts by product area and release. The revised event carries an approved event name, coarse route class, release identifier, and outcome. If optional measurement is disabled, that event is not queued. Operational error reporting still follows its separate approved contract, with private text redacted and retention bounded. A failed export remains visible to the user regardless of analytics choice.',
    implementation='Define events centrally with an allowlisted schema and explicit field types. Reject unknown properties, raw URLs, free-text notes, and unreviewed identifiers at the collection boundary. Evaluate the current preference before placing an event in memory, browser storage, or a transport queue. When the preference changes, stop new optional events, clear unsent optional batches under policy, and avoid replaying old events on a later sign-in. Keep server-side and client-side collection aligned; disabling a browser tag does not stop server emissions. Validate both the event content and the destination in tests.',
    cost='Schema validation is O(k) in the number of event fields, usually small. Batching can lower request overhead but creates stored events that need a cancellation and expiry rule. Counting coarse outcomes may lose fine-grained analysis, yet it reduces collection and review burden. Retaining every raw event increases storage roughly with event rate times retention duration and can raise investigation exposure. Measure rejection of unknown fields, batch age, events sent after preference changes, and whether the chosen aggregate still answers the product question.',
    failure='A UI toggle disables the analytics tag, but a queued batch from the old session flushes on the next page load. The external recipient still receives records after the preference changed. Clear or suppress unsent optional events according to the approved rule. Another event schema permits a generic details object; a developer later inserts the full case note. Replace it with named allowlisted fields and fail the test when new keys appear. Inspect network payloads, not only the event builder source, to catch SDK-added context.',
    drill='Specify the Export-start question and the smallest event that answers it. Submit valid events and attempt to add an email, full URL, case note, and unknown property; confirm each is rejected. Queue an event, change the optional measurement preference, go offline and online, and inspect whether any suppressed event is sent. Test both browser and server emission paths. Compare storage and query cost under the chosen retention interval without inventing a universal period.',
    decision='Collect only approved fields for a stated measurement question, and enforce the choice before any optional transfer.',
    code='function approvedExportEvent(input) {\n  const allowedOutcomes = new Set(["started", "failed", "completed"]);\n  if (!allowedOutcomes.has(input.outcome)) throw new Error("unknown outcome");\n  return { event: "export_action", routeClass: "case-review", outcome: input.outcome };\n}\nconsole.log(JSON.stringify(approvedExportEvent({ outcome: "started", caseNote: "private" })));\n// Output: {"event":"export_action","routeClass":"case-review","outcome":"started"}',
    checks=['Optional events are suppressed before storage or transfer.','Unknown and private fields cannot pass the event schema.','Client and server emissions follow the same approved choice.'], mistakes=['Using a generic details object for arbitrary event data.','Clearing a dashboard while leaving collection active.','Ignoring queued batches when a preference changes.'], related=['web-tech/telemetry-minimization-and-retention','web-tech/cross-tab-invalidation-and-version-checks','web-tech/data-retention-export-and-erasure']),
    dict(hub=1, path='web-tech/embedded-widget-storage-and-fallback', title='Embedded Widget Storage and Fallback', summary='Design embeds that work when third-party storage is partitioned or unavailable.',
    definition='An embedded widget runs in a context that may not share the same storage access as a top-level page. Browsers can block or partition third-party cookies and other state, and availability differs by browser and user settings. Do not treat an embed’s ability to read an unpartitioned cookie as a stable login contract. Build a clear fallback: the user can open the service in its own top-level context, sign in through an approved flow, or complete the local task without the widget. Any request for additional storage access is a separate, user-facing decision and should be tied to an explicit need.',
    case='A support widget inside a case-review page expects its own global cookie to identify reviewer 29. On a privacy-restricted browser the frame loads signed out and loops between a spinner and a login attempt. The host page should not send the case note or session token to make the widget appear signed in. Instead, it displays Open support in a separate page or a local contact path. If the widget needs a case reference, send a narrow server-issued reference after user action and authorization, with an expiry and purpose. The review form remains usable without support.',
    implementation='Test the widget in first-party and embedded contexts, with cookies blocked, partitioned, and cleared. Treat feature detection and storage-access requests as conditional paths; support and prompt behavior vary. Sandbox the frame to the capabilities it actually needs, validate message origins and payload shapes, and never transfer the host session credential through postMessage. Avoid assuming partitioned storage persists across all contexts or devices. Provide a timeout and fallback when the embed cannot authenticate or its vendor is down. Keep the host’s own authorization independent of the widget state.',
    cost='A widget adds a remote document, scripts, storage, and connection work even if the user never opens it. Deferring load can save those resources at the cost of a short wait when support is requested. A top-level fallback may add a navigation step but avoids fragile cross-site storage assumptions. Repeated failed authentication loops waste network requests and can strand users. Measure load time, failed frame initialization, login-loop count, fallback completion, and the bytes sent to the vendor. Do not optimize away the fallback before testing real privacy settings.',
    failure='A widget passes in the development browser because third-party cookies are allowed there, then fails for users with stricter settings. The app shows a blank panel and prevents submission until support loads. Make the panel optional and expose a direct route. Another fix sends a bearer token in a frame message without verifying target origin; a substituted frame can receive it. Use a narrow, server-validated reference or no host credential at all. Test the message path, blocked storage, network failure, and account switch.',
    drill='Open the review page with the widget blocked and confirm the case can still be saved. Repeat with storage partitioning and with no third-party cookie access. Trigger support deliberately and observe the frame’s requests and message payloads. Substitute an unexpected frame origin in a test and verify no secret is sent. Change accounts while support is open and check that the widget cannot present the old account as the current reviewer.',
    decision='Assume embedded storage can be limited and keep the host workflow independent of the vendor’s session.',
    code='function supportRoute(embedReady, storageAvailable) {\n  return embedReady && storageAvailable ? "embedded-support" : "top-level-support";\n}\nconsole.log(supportRoute(true, false));\n// Output: top-level-support',
    checks=['The host task completes when the widget cannot load or authenticate.','No host session credential crosses the frame message boundary.','Blocked and partitioned storage paths have usable outcomes.'], mistakes=['Assuming a global third-party cookie is always available.','Blocking the primary form until an optional widget starts.','Sending a host token to an unverified frame.'], related=['web-tech/embedding-and-browser-capability-headers','web-tech/session-cookie-and-csrf-boundary','web-tech/browser-storage-boundary']),
    dict(hub=1, path='web-tech/preference-change-propagation-and-audit', title='Preference Change Propagation and Audit', summary='Make optional-data choices take effect across tabs, queues, server events, and later sessions.',
    definition='A privacy preference is a state transition with a scope and an effective time. A toggle in one browser tab is only one representation of that decision. Other open tabs, event queues, server-side jobs, and future sessions may continue optional collection unless the preference is propagated and checked at collection time. Define which account or device the choice belongs to, how it is versioned, and which data paths it controls. The application should explain the actual effect without implying that previously sent data can be recalled from an external service.',
    case='Reviewer 29 turns optional product measurement off in one tab while a second tab still displays case 47. The first tab updates its state and sends a versioned preference change to the server. The second tab receives an invalidation signal or checks the version before its next event, then stops new optional collection. A pending browser batch is discarded under policy. A scheduled server job reads the current preference before emitting any optional aggregate. On a different device, the server-backed account choice is applied after sign-in. Operational security signals remain governed by their distinct contract.',
    implementation='Store a trusted current preference and monotonically increasing version at the correct scope. Broadcast a change for fast local response, but let each tab recheck authoritative state because messages can be missed by suspended pages. Gate event construction and delivery, not only SDK initialization. For queued events, decide whether to discard, retain locally, or send based on an approved policy, then test that rule. Server workers should read a current version before optional emission. Keep a minimal audit of when and how the setting changed without copying private event payloads into the audit itself.',
    cost='A version comparison is O(1); fetching it for every event may add network and database traffic. A short-lived local cache can reduce reads but creates a bounded delay before other tabs comply. Broadcast messages are cheap but not guaranteed to reach suspended contexts. Queue cleanup touches O(n) pending optional events, so keep batches bounded and expiring. Measure maximum observed delay from preference change to no new optional transfers across tabs and server paths. A stored preference is useful only if its enforcement latency matches the product promise.',
    failure='The setting page says measurement is off, but a background tab flushes an old batch when it wakes from suspension. Add a current-version check before transport and discard suppressed events. Another system reads the preference only when a daily worker starts, then sends events for a person who opted out during the run. Define a check boundary that matches the promised effective time. Test account switching, offline-to-online replay, server job retries, missed broadcasts, and a preference change during an in-flight request. Report the precise effect; an already completed transfer cannot be undone by the toggle.',
    drill='Open two tabs for reviewer 29 and queue events in both. Change the preference in one tab while the other is suspended, then wake and reconnect it. Inspect network traffic and pending storage for any optional transfer. Start a server job, change the preference during execution, and verify the documented cutoff. Sign in on another device and check the account-scoped choice. Compare audit records with the actual policy version without logging case content.',
    decision='Version the choice, propagate it promptly, and enforce it again where optional data is collected or sent.',
    code='function maySendOptionalEvent(eventVersion, preference) {\n  return preference.enabled && eventVersion === preference.version;\n}\nconsole.log(maySendOptionalEvent(4, { enabled: false, version: 5 }));\n// Output: false',
    checks=['All open and resumed tabs stop optional sends within the stated bound.','Queued and server-generated events check the current policy.','The audit records decisions without retaining private event bodies.'], mistakes=['Treating a local toggle as the only source of truth.','Assuming suspended tabs receive broadcasts immediately.','Promising a toggle can retract an already sent event.'], related=['web-tech/cross-tab-invalidation-and-version-checks','web-tech/telemetry-minimization-and-retention','web-tech/retention-inventory-and-expiry-workflows']),
]

assert len(hubs) == 2 and len(lessons) == 8
for number, hub in enumerate(hubs):
    path = hub['path']
    assert path not in by_path
    entry = copy.deepcopy(by_path['web-tech/production-signals-and-incident-decisions'])
    entry.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, 'aitrove:' + path)), path=path, title=hub['title'], summary=hub['summary'], sort_order=2700 + number, created_at=stamp, updated_at=stamp, published_at=stamp)
    entry['data'] = {'subject_root':'web-tech/web-technology','section_path':path,'content_format':'html','seo_ready':False,'modules':[],'resource_tabs':[{'title':'Web Development','path':'web-tech/web-technology'},{'title':'Projects','path':'web-tech/web-technology/project'},{'title':'Quizzes','path':'web-tech/quizzes'}]}
    entries.append(entry)
    by_path[path] = entry

for number, topic in enumerate(lessons):
    path = topic['path']
    assert path not in by_path
    subprocess.run(['node','--check','--input-type=module'], input=topic['code'], text=True, capture_output=True, check=True)
    entry = copy.deepcopy(by_path['web-tech/trace-context-across-request-and-job'])
    entry.update(id=str(uuid.uuid5(uuid.NAMESPACE_URL, 'aitrove:' + path)), path=path, title=topic['title'], summary=topic['summary'], sort_order=2710 + number, created_at=stamp, updated_at=stamp, published_at=stamp)
    hub_path = hubs[topic['hub']]['path']
    related = [hub_path] + [item['path'] for item in lessons if item['hub'] == topic['hub'] and item['path'] != path] + topic['related']
    body = p(topic['definition']) + '<h2>Working case</h2>' + p(topic['case'])
    body += '<h2>Implementation boundary</h2><pre><code class="language-javascript">' + html.escape(topic['code'], quote=False) + '</code></pre>' + p(topic['implementation'])
    body += '<h2>Cost and boundaries</h2>' + p(topic['cost']) + '<h2>Failure trace</h2>' + p(topic['failure'])
    body += '<h2>Verification</h2><ul>' + ''.join('<li>' + html.escape(item) + '</li>' for item in topic['checks']) + '</ul>'
    body += '<h2>Practice drill</h2>' + p(topic['drill']) + '<h2>Decision note</h2>' + p(topic['decision'])
    body += '<h3>Common Mistakes</h3><ul>' + ''.join('<li>' + html.escape(item) + '</li>' for item in topic['mistakes']) + '</ul>'
    body += '<h2>Connected lessons</h2><p>' + '; '.join(link(item) for item in related) + '.</p>'
    entry['body'] = body
    entry['data'] = {'subject_root':'web-tech/web-technology','section_path':hub_path,'content_format':'html','seo_ready':False,'kind':'tutorial','author_path':'authors/aitrove-editorial','reading_minutes':max(6, round(len(re.findall(r'\b\w+\b', re.sub(r'<[^>]+>', ' ', body))) / 155)), 'related':related}
    entries.append(entry)
    by_path[path] = entry

for number, hub in enumerate(hubs):
    group = [item for item in lessons if item['hub'] == number]
    entry = by_path[hub['path']]
    entry['data']['modules'] = [{'title':hub['title'],'summary':hub['summary'],'lessons':[item['path'] for item in group]}]
    entry['body'] = p(hub['overview']) + '<h2>Topics in this track</h2><ul>' + ''.join('<li>' + link(item['path']) + ' — ' + html.escape(item['summary']) + '</li>' for item in group) + '</ul>'
    entry['body'] += '<h2>Prerequisite paths</h2><p>' + '; '.join(link(item) for item in hub['bridges']) + '.</p>'
    entry['body'] += '<h2>Neighbor track</h2><p>' + link(hubs[1 - number]['path']) + '.</p>'

root_entry = by_path['web-tech/web-technology']
for number, hub in enumerate(hubs):
    group = [item for item in lessons if item['hub'] == number]
    root_entry['data']['modules'].append({'title':hub['title'],'summary':hub['summary'],'lessons':[hub['path']] + [item['path'] for item in group]})
    root_entry['body'] += '<h2>' + link(hub['path']) + '</h2>' + p(hub['summary']) + '<ul>' + ''.join('<li>' + link(item['path']) + ' — ' + html.escape(item['summary']) + '</li>' for item in group) + '</ul>'
root_entry['updated_at'] = stamp

crosslinks = {
    'web-tech/inclusive-interface-engineering':[hubs[0]['path'], lessons[0]['path']],
    'web-tech/image-variants-and-delivery':[lessons[0]['path'], lessons[2]['path']],
    'web-tech/data-table-versus-interactive-grid':[lessons[1]['path']],
    'web-tech/route-scroll-and-focus-restoration':[lessons[3]['path']],
    'web-tech/browser-security-and-data-stewardship':[hubs[1]['path'], lessons[4]['path']],
    'web-tech/telemetry-minimization-and-retention':[lessons[5]['path'], lessons[7]['path']],
    'web-tech/embedding-and-browser-capability-headers':[lessons[6]['path']],
    'web-tech/data-retention-export-and-erasure':[lessons[7]['path']],
}
for path, targets in crosslinks.items():
    entry = by_path[path]
    entry['body'] += '<h2>Further connections</h2><p>' + '; '.join(link(item) for item in targets) + '.</p>'
    entry['updated_at'] = stamp

fixture.write_text(json.dumps(entries, ensure_ascii=False, indent=2) + '\n')
print(json.dumps({'new_hubs':len(hubs),'new_lessons':len(lessons)}))
